// sigbugsDir is the signature rejection set, generated by
// `ctfbundle sigbugs` (go generate ./testdata/generate.go).
const sigbugsDir = "../bundle/testdata/sigbugs"

func readSigbug(t *testing.T, name string) []byte {
	t.Helper()
	b, err := os.ReadFile(filepath.Join(sigbugsDir, name))
	if err != nil {
		t.Fatal(err)
	}
	return b
}

// sigbugEnvelope returns manifest.dsse.json, the first entry of a fixture.
func sigbugEnvelope(t *testing.T, name string) []byte {
	t.Helper()
	zr, err := gzip.NewReader(bytes.NewReader(readSigbug(t, name+".tar.gz")))
	if err != nil {
		t.Fatal(err)
	}
	tr := tar.NewReader(zr)
	if h, err := tr.Next(); err != nil || h.Name != "manifest.dsse.json" {
		t.Fatalf("%s: first entry %v %v", name, h, err)
	}
	env, err := io.ReadAll(tr)
	if err != nil {
		t.Fatal(err)
	}
	return env
}

// ctftestKeyring is keyring_test.json, the keys a ctftest build trusts. It is
// parsed here so the cases also run in release builds.
func ctftestKeyring(t *testing.T) *Keyring {
	t.Helper()
	raw, err := os.ReadFile("keyring_test.json")
	if err != nil {
		t.Fatal(err)
	}
	return mustKeyring(t, raw, true)
}

func kidFor(t *testing.T, kr *Keyring, purpose string) string {
	t.Helper()
	for _, k := range kr.Keys() {
		if k.Purpose == purpose {
			return k.KID
		}
	}
	t.Fatalf("no %s key", purpose)
	return ""
}

// TestSigBugs is the oracle at the DSSE layer: every fixture fails
// with its own error, and the positive controls show that the one broken
// property is the only reason.
func TestSigBugs(t *testing.T) {
	test := ctftestKeyring(t)
	bundleKID := kidFor(t, test, PurposeBundle)
	untrusted := mustKeyring(t, readSigbug(t, "untrusted-key.keyring.json"), false)
	edRaw := readSigbug(t, "ed25519-release.keyring.json")
	ed := mustKeyring(t, edRaw, true)
	empty := mustKeyring(t, []byte(`{"format":"compliancetf.keyring/v1","keys":[]}`), false)
	revoked, err := ParseRevocations([]byte(`{"format":"compliancetf.revocations/v1","epoch":3,"revoked_keys":[{"kid":"` +
		bundleKID + `","revoked_at":"2026-10-02T00:00:00Z"}],"revoked_bundles":[],"revoked_controls":[]}`))
	if err != nil {
		t.Fatal(err)
	}
	none := NoRevocations()

	cases := []struct {
		name string
		kr   *Keyring
		revs Revocations
		want string
	}{
		{"unsigned", test, none, "dsse: need 1 to 8 signatures"},
		{"tampered-payload", test, none, "dsse: no valid signature: signature 0: signature invalid"},
		{"untrusted-key", test, none, "dsse: no valid signature: signature 0: key not in keyring"},
		{"empty-keyring", empty, none, "dsse: no valid signature: signature 0: key not in keyring"},
		{"ed25519-release", test, none, "dsse: no valid signature: signature 0: key not in keyring"},
		{"revoked-in-grace", test, revoked, "dsse: no valid signature: signature 0: key revoked"},
	}
	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			_, err := c.kr.Verify(sigbugEnvelope(t, c.name), PayloadBundleManifest, c.revs)
			if err == nil || err.Error() != c.want {
				t.Fatalf("got %v, want %q", err, c.want)
			}
		})
	}

	// Payload type and key purpose bind: the good manifest presented as a
	// profile, and the same payload signed by the trusted profile key.
	good := sigbugEnvelope(t, "empty-keyring")
	if _, err := test.Verify(good, PayloadProfile, none); err == nil ||
		err.Error() != `dsse: payload type mismatch, want "`+PayloadProfile+`"` {
		t.Errorf("manifest as profile: %v", err)
	}
	var e envelope
	if err := json.Unmarshal(good, &e); err != nil {
		t.Fatal(err)
	}
	payload, _ := base64.StdEncoding.DecodeString(e.Payload)
	byProfileKey := sign(t, PayloadBundleManifest, payload, testkeys.Profile())
	_ = kidFor(t, test, PurposeProfile)
	wantPurpose := "dsse: no valid signature: signature 0: key purpose profile, payload needs bundle"
	if _, err := test.Verify(byProfileKey, PayloadBundleManifest, none); err == nil || err.Error() != wantPurpose {
		t.Errorf("manifest signed by the profile key: got %v, want %q", err, wantPurpose)
	}

	// Positive controls: the same bytes verify once the one broken property
	// is fixed.
	controls := []struct {
		name string
		kr   *Keyring
	}{
		{"empty-keyring", test},
		{"revoked-in-grace", test},
		{"untrusted-key", untrusted},
		{"ed25519-release", ed},
	}
	for _, c := range controls {
		if _, err := c.kr.Verify(sigbugEnvelope(t, c.name), PayloadBundleManifest, none); err != nil {
			t.Errorf("control %s: %v", c.name, err)
		}
	}
	// The Ed25519 bundle key is refused by the release algorithm allowlist.
	if _, err := parseKeyring(edRaw, false); err == nil || err.Error() != "keyring: key 0: alg Ed25519 is not trusted in this build" {
		t.Errorf("ed25519-release keyring under the release allowlist: %v", err)
	}
}

// TestKeyAlgAllowlist: a keyring entry with any alg but ES256 (Ed25519 only
// where allowed) rejects the keyring, and the alg must match the SPKI.
func TestKeyAlgAllowlist(t *testing.T) {
	p256, ed := newP256(t), newEd25519(t)
	for _, alg := range []string{"ES384", "ES512", "RS256", "PS256", "EdDSA", "es256", "ed25519", "none", ""} {
		raw := keyringBytes(entry(t, p256, alg, PurposeBundle, nb, na))
		if _, err := parseKeyring(raw, true); err == nil || err.Error() != `keyring: key 0: alg "`+alg+`" not allowed` {
			t.Errorf("alg %q: %v", alg, err)
		}
	}
	cases := []struct {
		name  string
		raw   []byte
		allow bool
		want  string
	}{
		{"Ed25519 in release", keyringBytes(entry(t, ed, AlgEd25519, PurposeProfile, nb, na)), false, "keyring: key 0: alg Ed25519 is not trusted in this build"},
		{"ES256 label on Ed25519 key", keyringBytes(entry(t, ed, AlgES256, PurposeProfile, nb, na)), true, "keyring: key 0: ES256 key is not ECDSA P-256"},
		{"Ed25519 label on P-256 key", keyringBytes(entry(t, p256, AlgEd25519, PurposeProfile, nb, na)), true, "keyring: key 0: Ed25519 key has the wrong type"},
	}
	for _, c := range cases {
		if _, err := parseKeyring(c.raw, c.allow); err == nil || err.Error() != c.want {
			t.Errorf("%s: got %v, want %q", c.name, err, c.want)
		}
	}
	if _, err := parseKeyring(keyringBytes(entry(t, p256, AlgES256, PurposeBundle, nb, na)), false); err != nil {
		t.Errorf("ES256 rejected: %v", err)
	}
}

// TestConfigAnchorsIgnored: keys planted in env, the state dir, the user
// config dir or the working directory add no trust. The compiled keyring is
// reloaded after planting, so a loader that read any of them would show here.
func TestConfigAnchorsIgnored(t *testing.T) {
	planted := readSigbug(t, "untrusted-key.keyring.json")
	_ = kidFor(t, mustKeyring(t, planted, false), PurposeBundle) // planted keys are real bundle keys; the error never names them
	env := sigbugEnvelope(t, "untrusted-key")

	dir := t.TempDir()
	for _, sub := range []string{"state", "config/compliancetf", "cwd"} {
		p := filepath.Join(dir, sub)
		if err := os.MkdirAll(p, 0o700); err != nil {
			t.Fatal(err)
		}
		for _, f := range []string{"keyring.json", "keyring_test.json", "trusted_keys.json"} {
			if err := os.WriteFile(filepath.Join(p, f), planted, 0o600); err != nil {
				t.Fatal(err)
			}
		}
	}
	t.Setenv("COMPLIANCETF_STATE_DIR", filepath.Join(dir, "state"))
	t.Setenv("XDG_CONFIG_HOME", filepath.Join(dir, "config"))
	t.Setenv("HOME", dir)
	for _, k := range []string{"COMPLIANCETF_KEYRING", "COMPLIANCETF_KEYRING_PATH", "COMPLIANCETF_TRUSTED_KEYS",
		"COMPLIANCETF_PUBLIC_KEYS", "COMPLIANCETF_PUBLIC_KEY", "COMPLIANCETF_SIGNING_KEYS", "COMPLIANCETF_TRUST_ANCHORS"} {
		t.Setenv(k, string(planted))
	}
	t.Chdir(filepath.Join(dir, "cwd"))

	fresh, err := loadEmbedded()
	if err != nil {
		t.Fatal(err)
	}
	compiled, err := Embedded()
	if err != nil {
		t.Fatal(err)
	}
	if len(fresh.Keys()) != len(compiled.Keys()) {
		t.Fatalf("keyring has %d keys after planting, compiled %d", len(fresh.Keys()), len(compiled.Keys()))
	}
	want := "dsse: no valid signature: signature 0: key not in keyring"
	for name, verify := range map[string]func() error{
		"fresh load": func() error { _, err := fresh.Verify(env, PayloadBundleManifest, NoRevocations()); return err },
		"Verify":     func() error { _, err := Verify(env, PayloadBundleManifest, NoRevocations()); return err },
	} {
		if err := verify(); err == nil || err.Error() != want {
			t.Errorf("%s: got %v, want %q", name, err, want)
		}
	}
}
